import socket,sys,time,json
import arena

def analyze(board, secs=30, moves=None, verbose=True):
 s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.connect('/run/match/opponent-stockfish.sock'); f=s.makefile('r');
 def send(x): s.sendall((x+'\n').encode())
 send('uci')
 for line in f:
  if line.strip()=='uciok':break
 send('setoption name Threads value 2');send('setoption name Hash value 256');send('isready')
 for line in f:
  if line.strip()=='readyok':break
 send('position startpos moves '+' '.join(m.uci() for m in board.move_stack) if board.move_stack else 'position fen '+board.fen())
 send('go movetime '+str(int(secs*1000))+(' searchmoves '+' '.join(moves) if moves else ''))
 last=None
 for line in f:
  line=line.strip()
  if line.startswith('info depth'):
   last=line
   if verbose:print(line,flush=True)
  if line.startswith('bestmove'):
   if verbose:print(line,flush=True)
   best=line.split()[1]; break
 send('quit');s.close()
 return best,last
if __name__=='__main__':
 b=arena.load_board();print('FEN',b.fen(),flush=True)
 analyze(b,float(sys.argv[1]) if len(sys.argv)>1 else 30,sys.argv[2:] or None)
